import 'dart:async';

import 'package:flutter/material.dart';

import '../themes/stack_colors.dart';
import '../widgets/custom_loading_overlay.dart';
import 'logger.dart';

Future<T> minWaitFuture<T>(Future<T> future, {required Duration delay}) async {
  final results = await Future.wait([future, Future<dynamic>.delayed(delay)]);

  return results.first as T;
}

Future<T?> showLoading<T>({
  Future<T>? whileFuture,
  Future<T> Function()? whileFutureAlt,
  required BuildContext context,
  required String message,
  String? subMessage,
  // Unused: the overlay is always on the root navigator.
  bool rootNavigator = false,
  bool opaqueBG = false,
  void Function(Exception)? onException,
  Duration? delay,
}) async {
  assert(
    (whileFuture != null || whileFutureAlt != null) &&
        !(whileFuture != null && whileFutureAlt != null) &&
        !(whileFuture == null && whileFutureAlt == null),
  );

  // The overlay goes on the root navigator (as showDialog does by
  // default) and is closed there: on desktop the caller usually sits in a
  // nested navigator, whose top route is the page, not this overlay.
  unawaited(
    showDialog<void>(
      context: context,
      useRootNavigator: true,
      barrierDismissible: false,
      builder: (_) => WillPopScope(
        onWillPop: () async => false,
        child: Container(
          color: Theme.of(context)
              .extension<StackColors>()!
              .overlay
              .withOpacity(opaqueBG ? 1.0 : 0.6),
          child: CustomLoadingOverlay(
            message: message,
            subMessage: subMessage,
            eventBus: null,
          ),
        ),
      ),
    ),
  );

  Exception? ex;
  T? result;

  try {
    if (delay != null) {
      result = await minWaitFuture(
        whileFutureAlt?.call() ?? whileFuture!,
        delay: delay,
      );
    } else {
      result = await (whileFutureAlt?.call() ?? whileFuture!);
    }
  } catch (e, s) {
    Logging.instance.w("showLoading caught: ", error: e, stackTrace: s);
    ex = e is Exception ? e : Exception(e.toString());
  }

  if (context.mounted) {
    Navigator.of(context, rootNavigator: true).pop();
    if (ex != null) {
      onException?.call(ex);
    }
  }

  return result;
}
